
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  clerk_name = EXCLUDED.clerk_name,
  sort_order = EXCLUDED.sort_order;



ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  detail = EXCLUDED.detail,
  category_color = EXCLUDED.category_color;


ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, plate=EXCLUDED.plate, type=EXCLUDED.type, seats=EXCLUDED.seats, status=EXCLUDED.status, driver=EXCLUDED.driver, dest=EXCLUDED.dest, sort_order=EXCLUDED.sort_order;

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, lead=EXCLUDED.lead, default_car_id=EXCLUDED.default_car_id, site=EXCLUDED.site, office_site_id=EXCLUDED.office_site_id, sort_order=EXCLUDED.sort_order;

ON CONFLICT (id) DO UPDATE SET emp_code=EXCLUDED.emp_code, pin_code=EXCLUDED.pin_code, name=EXCLUDED.name, job_title=EXCLUDED.job_title, app_role=EXCLUDED.app_role, is_developer=EXCLUDED.is_developer, team_id=EXCLUDED.team_id, office_site_id=EXCLUDED.office_site_id, is_lead=EXCLUDED.is_lead;

ON CONFLICT (role_key, module_key) DO UPDATE SET can_view=EXCLUDED.can_view, can_edit=EXCLUDED.can_edit, can_approve=EXCLUDED.can_approve, description=EXCLUDED.description;

ON CONFLICT (date_val, team_id, target_key) DO UPDATE SET task_desc=EXCLUDED.task_desc, vehicle_id=EXCLUDED.vehicle_id, updated_by=EXCLUDED.updated_by;










ON CONFLICT (date_val, worker_id) DO UPDATE SET status=EXCLUDED.status, punch_in=EXCLUDED.punch_in, punch_out=EXCLUDED.punch_out, remark_note=EXCLUDED.remark_note;